float wave(float xPos,float wavelength,float amplitude){//for 1 wave
        return (sin(xPos*wavelength))/amplitude;
    }

    float waveAdd(float alpha,float beta){//for more waves
        return 2.*cos((alpha-beta)/2.)*sin((alpha+beta)/2.);
    }

//settings
#define lineWidth .005
#define lineBlur .010
#define speed .5
#define waveSize 15.

//arrayed wave, add one for each, if using regular GSLS just do a uniform for it
#define ARRAYSIZE 4
#define WAVE0 10.5
#define WAVE1 8.5
#define WAVE2 .5
#define WAVE3 20.

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    //centering thingy
    uv.x *= iResolution.x/iResolution.y;


    //animate it!!
    vec2 still = uv;
    uv.x += speed*iTime;

    //the waves
    float cool = waveAdd(uv.x*2.,uv.x*2.);
    float cooler = waveAdd(cool,uv.x*1.);//I guess you could keep going with this


    float coolest[ARRAYSIZE];//arrayed version
    coolest[0] = WAVE0;
    coolest[1] = WAVE1;
    coolest[2] = WAVE2;
    coolest[3] = WAVE3;


    float waveBuffer = waveAdd(coolest[0]*uv.x,coolest[1]*uv.x);
    for(int i = 2; i < coolest.length();i++){
        waveBuffer = waveAdd(waveBuffer,coolest[i]*uv.x);
    }

    float theMostCool = waveBuffer;

    //add in wave at "theMostCool"
    float finalWave = abs(uv.y-.5-theMostCool/waveSize);

    vec3 col = vec3(smoothstep(lineWidth,lineBlur,finalWave));

    //rolling? ball
    vec2 ball = vec2(still.x-.8,finalWave-lineWidth-.05);
    col *= vec3(step(.05,length(ball)));

    col += vec3(abs(step(.045,length(ball))-1.)*.7,abs(step(.045,length(ball))-1.)*.6,abs(step(.045,length(ball))-1.)*.7);

    //cool effect?
    col -= vec3(length(ball),length(ball-.2),.0);



    /* party mode!
    col.x *= cos(iTime*5.);
    col.y *= sin(iTime*5.+5.);*/

    // Output to screen
    fragColor = vec4(col,1.0);
}
